import numpy as np, itertools
from fractions import Fraction as F
E = weights['embedding.weight'].astype(np.float64); L = weights['linear.weight'].astype(np.float64); U = weights['unembedding.weight'].astype(np.float64)
M = U @ L @ E
mx = np.array([max(M[j,a] for j in range(8) if j!=a) for a in range(8)])
top = np.maximum(mx, np.diag(M)); dm = np.diag(M)-mx
# shifted scheme: columns in decreasing token order over T; shift for row j of column a: d_j if j in T and j>a else eps.
# d_t = M'[t,t]-mx'_t where M' is the shifted column t: M'[j,t]=M[j,t]+s_j^{(t)}; s_t = eps.
def plan(T, eps):
    T = sorted(T, reverse=True)
    d = {}
    Mp = {}
    for t in T:
        s = {j: (d[j] if (j in d and j>t) else eps) for j in range(8)}
        col = {j: M[j,t]+s[j] for j in range(8)}
        Mp[t]=col
        mxp = max(col[j] for j in range(8) if j!=t)
        d[t] = col[t]-mxp
    res = {}
    for a in T:
        topp = max(Mp[a][j] for j in range(8))
        for m in T:
            if m>a:
                res[(a,m)] = topp <= Mp[a][m]
    return d, res
for eps in [1.0, 0.5, 0.1, 0.001]:
    d, res = plan(range(8), eps)
    fails = [p for p,v in res.items() if not v]
    print("eps", eps, "d>=eps all:", all(v>=eps for v in d.values()), "fails:", fails)
