rf = [(a,m) for a in range(8) for m in range(a+1,8) if not ((mx[a]-M[m,a] < dm[m]) and (M[a,a]-M[m,a] < M[m,m]-M[a,m]))]
print("plain top fails", tf); print("rpair fails", rf)
# margins of the failing pairs in shifted scheme with eps=0.001
d, res = plan(range(8), 0.001)
for (a,m) in [p for p,v in res.items() if not v]:
    topp = max(M[j,a]+(d[j] if j>a else 0.001) for j in range(8))
    print((a,m), "top'", topp, "M'[m,a]", M[m,a]+d[m], "margin", M[m,a]+d[m]-topp, "argmax", int(np.argmax([M[j,a]+(d[j] if j>a else 0.001) for j in range(8)])))
